\begin{array}{r l} & {\text {左边} = \lim _ {n \to \infty} n \Bigg [  \sum_ {k = 1} ^ {n} \int_ {x _ {k - 1}} ^ {x _ {k}} f (x)   \mathrm{d} x -  \sum_ {k = 1} ^ {n} f (x _ {k}) (x _ {k} - x _ {k - 1}) \Bigg ] = \lim _ {n \to \infty} n  \sum_ {k = 1} ^ {n} \int_ {x _ {k - 1}} ^ {x _ {k}} \big [ f (x) - f (x _ {k}) \big ]   \mathrm{d} x} \\ & {\qquad = \lim _ {n \to \infty} n  \sum_ {k = 1} ^ {n} \int_ {x _ {k - 1}} ^ {x _ {k}} f ^ {\prime} (\xi_ {k}) (x - x _ {k})   \mathrm{d} x \quad (\text {微分中值定理}, \xi_ {k} \text {介于} x _ {k} \text {与} x \text {之间})} \\ & {\qquad = \lim _ {n \to \infty} n  \sum_ {k = 1} ^ {n} f ^ {\prime} (\eta_ {k}) \int_ {x _ {k - 1}} ^ {x _ {k}} (x - x _ {k})   \mathrm{d} x \quad (\text {积分第一中值定理}, x _ {k - 1} \leqslant \eta_ {k} \leqslant x _ {k})} \\ & {\qquad = \lim _ {n \to \infty} n  \sum_ {k = 1} ^ {n} f ^ {\prime} (\eta_ {k}) \Bigg (- \frac {1}{2} \Bigg) (x _ {k} - x _ {k - 1}) ^ {2} = - \frac {b - a}{2} \lim _ {n \to \infty}  \sum_ {k = 1} ^ {n} f ^ {\prime} (\eta_ {k}) \Delta x _ {k}} \\ & {\qquad {\frac {\text {定积分}}{\text {的定义}}} - {\frac {b - a}{2}} \int_ {a} ^ {b} f ^ {\prime} (x)   \mathrm{d} x = {\frac {b - a}{2}} [ f (a) - f (b) ] = \text {右边}.} \end{array}\tag{①}
